const r = $('CA87P_Generar_y_enviar').first().json, v = $input.first().json;
const d = r.datos || {};
const act = (k) => Number(((d.actividad || {})[k] || {}).total || 0);
const pf = (ok) => (ok ? 'PASA' : 'FALLA');
const casos = [
  { caso: 'C1 genera el reporte de prueba y lo envia', esperado: 'enviado, es_prueba, asunto con [PRUEBA]', resultado: pf(r.estado === 'enviado' && r.es_prueba === true && String(r.asunto).includes('[PRUEBA]')), detalle: JSON.stringify({ estado: r.estado, es_prueba: r.es_prueba, asunto: r.asunto }) },
  { caso: 'C2 cola pendiente del reporte = conteo independiente', esperado: String(Number(v.cola)), resultado: pf(Number(d.cola_pendiente_total) === Number(v.cola)), detalle: JSON.stringify({ reporte: d.cola_pendiente_total, independiente: Number(v.cola) }) },
  { caso: 'C3 aprobaciones sin decision del reporte = conteo independiente', esperado: String(Number(v.aprob)), resultado: pf(Number(d.aprobaciones_sin_decision) === Number(v.aprob)), detalle: JSON.stringify({ reporte: d.aprobaciones_sin_decision, independiente: Number(v.aprob) }) },
  { caso: 'C4 actividad A04 de los ultimos 7 dias = conteo independiente', esperado: String(Number(v.a04)), resultado: pf(act('A04') === Number(v.a04)), detalle: JSON.stringify({ reporte: act('A04'), independiente: Number(v.a04) }) },
  { caso: 'C5 actividad A11 (monitoreo) = conteo independiente', esperado: String(Number(v.a11)), resultado: pf(act('A11') === Number(v.a11)), detalle: JSON.stringify({ reporte: act('A11'), independiente: Number(v.a11) }) },
  { caso: 'C6 el reporte queda marcado como enviado y de prueba en la base', esperado: 'enviado true, es_prueba true', resultado: pf(v.enviado === true && v.es_prueba === true), detalle: JSON.stringify({ enviado: v.enviado, es_prueba: v.es_prueba }) },
  { caso: 'C7 el correo llego al buzon de pruebas', esperado: 'Revisar a mano: asunto ' + r.asunto, resultado: 'MANUAL', detalle: 'Buscar en <CORREO>' },
];
return casos.map((c) => ({ json: c }));
